/**
 * 小程序 C 端（访客可见页面）国际化。
 *
 * 与 mobile-app 的 `src/i18n/index.ts` 保持同一「zustand store + messages 字典 +
 * `t(key, params?)`」方案，翻译文案直接复用 mobile-app / frontend-web 已有的
 * pub.* 口径（zh / en / th 三语一致）。
 *
 * 语言持久化用 Taro 本地 storage（对齐小程序 `stores/auth.ts` / `location.ts` 的写法），
 * 默认 'zh'——因此仅覆盖访客公开页，其余 B 端页面保持中文不受影响。
 */
import { create } from 'zustand'
import Taro from '@tarojs/taro'

export type AppLang = 'zh' | 'en' | 'th'

export const LANG_LABELS: Record<AppLang, string> = {
  zh: '简体中文',
  en: 'English',
  th: 'ไทย',
}

export const LANGS: AppLang[] = ['zh', 'en', 'th']

const LANG_STORAGE_KEY = 'app_lang'

interface I18nState {
  lang: AppLang
  setLang: (lang: AppLang) => void
  /**
   * 取文案。`params` 用于替换文案里的 `{name}` 占位（如 'pub.totalCount' 的 `{n}`）。
   * 传入 params 时按字面量全局替换，不做复数/性别处理——本项目不需要。
   */
  t: (key: string, params?: Record<string, string | number>) => string
}

